using System;
using System.Diagnostics;
using System.Drawing;
using System.IO;
using System.Windows.Forms;

namespace SharkQuantInstaller
{
    public class InstallerForm : Form
    {
        private ProgressBar prgBar;
        private Label lblStatus;
        private Button btnAction;
        private CheckBox chkDesktop;
        private CheckBox chkLaunch;
        private Timer animTimer;
        private int currentStep = 0;
        private bool isFinished = false;

        private const string EXE_BASE64 = "";
        private const string ICO_BASE64 = "";

        [STAThread]
        public static void Main()
        {
            Application.EnableVisualStyles();
            Application.SetCompatibleTextRenderingDefault(false);
            Application.Run(new InstallerForm());
        }

        public InstallerForm()
        {
            this.Text = "Shark Traders AI — Setup Wizard";
            this.Size = new Size(560, 470);
            this.StartPosition = FormStartPosition.CenterScreen;
            this.FormBorderStyle = FormBorderStyle.FixedDialog;
            this.MaximizeBox = false;
            this.MinimizeBox = true;
            this.BackColor = Color.FromArgb(10, 14, 23); // #0A0E17

            // Load icon if possible
            try
            {
                byte[] iconBytes = Convert.FromBase64String(ICO_BASE64);
                using (MemoryStream ms = new MemoryStream(iconBytes))
                {
                    this.Icon = new Icon(ms);
                }
            }
            catch { }

            // 1. Header Banner
            Panel topPanel = new Panel();
            topPanel.Dock = DockStyle.Top;
            topPanel.Height = 85;
            topPanel.BackColor = Color.FromArgb(15, 23, 38);
            this.Controls.Add(topPanel);

            Label lblTitle = new Label();
            lblTitle.Text = "🦈 SHARK TRADERS AI";
            lblTitle.Font = new Font("Segoe UI", 16, FontStyle.Bold);
            lblTitle.ForeColor = Color.FromArgb(255, 230, 0); // Gold
            lblTitle.Location = new Point(20, 14);
            lblTitle.AutoSize = true;
            topPanel.Controls.Add(lblTitle);

            Label lblSubtitle = new Label();
            lblSubtitle.Text = "Institutional Quant & Global Macro SMC Trading Platform — Windows Edition";
            lblSubtitle.Font = new Font("Segoe UI", 9.5f, FontStyle.Regular);
            lblSubtitle.ForeColor = Color.FromArgb(0, 229, 255); // Cyan
            lblSubtitle.Location = new Point(22, 48);
            lblSubtitle.AutoSize = true;
            topPanel.Controls.Add(lblSubtitle);

            // 2. Info Box
            Panel infoBox = new Panel();
            infoBox.Location = new Point(24, 105);
            infoBox.Size = new Size(495, 125);
            infoBox.BackColor = Color.FromArgb(18, 25, 40);
            infoBox.BorderStyle = BorderStyle.FixedSingle;
            this.Controls.Add(infoBox);

            Label lblInfo = new Label();
            lblInfo.Text = "Welcome to the Shark Traders AI Installation Wizard.\n\n" +
                           "• Destination: %LOCALAPPDATA%\\SharkTradersAI\\\n" +
                           "• Features: Real-Time Charts, Multi-Timeframe SMC Scanner, Voice Engine\n" +
                           "• Shortcuts: Desktop & Start Menu with Official 3D Shark Icon";
            lblInfo.Font = new Font("Segoe UI", 9.5f, FontStyle.Regular);
            lblInfo.ForeColor = Color.FromArgb(226, 232, 240);
            lblInfo.Location = new Point(14, 14);
            lblInfo.Size = new Size(465, 95);
            infoBox.Controls.Add(lblInfo);

            // 3. Options Checkboxes
            chkDesktop = new CheckBox();
            chkDesktop.Text = "Create Desktop Shortcut with 3D Shark Icon (أيقونة سطح المكتب)";
            chkDesktop.Checked = true;
            chkDesktop.Font = new Font("Segoe UI", 9.5f);
            chkDesktop.ForeColor = Color.FromArgb(203, 213, 225);
            chkDesktop.Location = new Point(24, 245);
            chkDesktop.AutoSize = true;
            this.Controls.Add(chkDesktop);

            chkLaunch = new CheckBox();
            chkLaunch.Text = "Launch Shark Traders AI when setup finishes (تشغيل البرنامج فوراً)";
            chkLaunch.Checked = true;
            chkLaunch.Font = new Font("Segoe UI", 9.5f);
            chkLaunch.ForeColor = Color.FromArgb(203, 213, 225);
            chkLaunch.Location = new Point(24, 275);
            chkLaunch.AutoSize = true;
            this.Controls.Add(chkLaunch);

            // 4. Status and Progress Bar
            lblStatus = new Label();
            lblStatus.Text = "Click 'Install Now' to begin installation.";
            lblStatus.Font = new Font("Segoe UI", 9f, FontStyle.Regular);
            lblStatus.ForeColor = Color.FromArgb(148, 163, 184);
            lblStatus.Location = new Point(24, 312);
            lblStatus.AutoSize = true;
            this.Controls.Add(lblStatus);

            prgBar = new ProgressBar();
            prgBar.Location = new Point(24, 335);
            prgBar.Size = new Size(495, 20);
            prgBar.Value = 0;
            this.Controls.Add(prgBar);

            // 5. Install / Finish Button
            btnAction = new Button();
            btnAction.Text = "⚡ INSTALL NOW";
            btnAction.Font = new Font("Segoe UI", 11, FontStyle.Bold);
            btnAction.BackColor = Color.FromArgb(0, 229, 255);
            btnAction.ForeColor = Color.FromArgb(0, 0, 0);
            btnAction.FlatStyle = FlatStyle.Flat;
            btnAction.FlatAppearance.BorderSize = 0;
            btnAction.Location = new Point(24, 370);
            btnAction.Size = new Size(495, 42);
            btnAction.Cursor = Cursors.Hand;
            btnAction.Click += BtnAction_Click;
            this.Controls.Add(btnAction);

            // Timer for installation progress simulation & step execution
            animTimer = new Timer();
            animTimer.Interval = 120;
            animTimer.Tick += AnimTimer_Tick;
        }

        private void BtnAction_Click(object sender, EventArgs e)
        {
            if (isFinished)
            {
                if (chkLaunch.Checked)
                {
                    LaunchApp();
                }
                this.Close();
                return;
            }

            btnAction.Enabled = false;
            currentStep = 0;
            animTimer.Start();
        }

        private void AnimTimer_Tick(object sender, EventArgs e)
        {
            currentStep += 15;
            if (currentStep > 100) currentStep = 100;
            prgBar.Value = currentStep;

            if (currentStep <= 25)
            {
                lblStatus.Text = "Creating application directories...";
            }
            else if (currentStep <= 55)
            {
                lblStatus.Text = "Extracting Shark Traders AI core binary and assets...";
            }
            else if (currentStep <= 85)
            {
                lblStatus.Text = "Registering 3D Shark icons and Desktop shortcuts...";
            }
            else
            {
                animTimer.Stop();
                DoInstallFiles();
                lblStatus.Text = "🎉 Installation completed successfully! (تم التثبيت بنجاح)";
                lblStatus.ForeColor = Color.FromArgb(0, 255, 102);

                btnAction.Text = "🚀 LAUNCH SHARK TRADERS AI";
                btnAction.BackColor = Color.FromArgb(0, 255, 102);
                btnAction.ForeColor = Color.Black;
                btnAction.Enabled = true;
                isFinished = true;
            }
        }

        private void DoInstallFiles()
        {
            try
            {
                string installDir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "SharkTradersAI");
                if (!Directory.Exists(installDir)) Directory.CreateDirectory(installDir);

                string exePath = Path.Combine(installDir, "SharkTradersAI.exe");
                string icoPath = Path.Combine(installDir, "icon.ico");

                byte[] exeBytes = Convert.FromBase64String(EXE_BASE64);
                File.WriteAllBytes(exePath, exeBytes);

                byte[] icoBytes = Convert.FromBase64String(ICO_BASE64);
                File.WriteAllBytes(icoPath, icoBytes);

                if (chkDesktop.Checked)
                {
                    CreateShortcut(Environment.GetFolderPath(Environment.SpecialFolder.Desktop), "Shark Traders AI", exePath, icoPath);

                    // Also check common/redirected desktops
                    string dDriveDesktop = @"D:\Antigravity\Desktop";
                    if (Directory.Exists(dDriveDesktop))
                    {
                        CreateShortcut(dDriveDesktop, "Shark Traders AI", exePath, icoPath);
                    }
                    string userDesktop = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Desktop");
                    if (Directory.Exists(userDesktop) && userDesktop != Environment.GetFolderPath(Environment.SpecialFolder.Desktop))
                    {
                        CreateShortcut(userDesktop, "Shark Traders AI", exePath, icoPath);
                    }
                }

                // Start Menu Shortcut
                string startMenu = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.StartMenu), "Programs");
                CreateShortcut(startMenu, "Shark Traders AI", exePath, icoPath);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Install Notice: " + ex.Message, "Shark Quant", MessageBoxButtons.OK, MessageBoxIcon.Warning);
            }
        }

        private void CreateShortcut(string folder, string name, string targetExe, string iconFile)
        {
            try
            {
                Type shellType = Type.GetTypeFromProgID("WScript.Shell");
                if (shellType != null)
                {
                    dynamic shell = Activator.CreateInstance(shellType);
                    string lnk = Path.Combine(folder, name + ".lnk");
                    dynamic shortcut = shell.CreateShortcut(lnk);
                    shortcut.TargetPath = targetExe;
                    shortcut.IconLocation = (File.Exists(iconFile) ? iconFile : targetExe) + ",0";
                    shortcut.Description = "Shark Traders AI — Institutional Quant Platform";
                    shortcut.WorkingDirectory = Path.GetDirectoryName(targetExe);
                    shortcut.Save();
                }
            }
            catch { }
        }

        private void LaunchApp()
        {
            try
            {
                string exePath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "SharkTradersAI", "SharkTradersAI.exe");
                if (File.Exists(exePath))
                {
                    Process.Start(exePath);
                }
            }
            catch { }
        }
    }
}
